    sides["hlc3_below_at_h"] = np.where(bits["hlc3_below_at_h"], -1.0, 0.0)
    occ["hlc3_cross_up"] = cross_up(hlc3_dist, 0.0)
    occ["hlc3_cross_down"] = cross_down(hlc3_dist, 0.0)
    bits["hlc3_cross_up"] = any_in_next(occ["hlc3_cross_up"], horizon)
    bits["hlc3_cross_down"] = any_in_next(occ["hlc3_cross_down"], horizon)
    sides["hlc3_cross_up"] = np.where(bits["hlc3_cross_up"], 1.0, 0.0)
    sides["hlc3_cross_down"] = np.where(bits["hlc3_cross_down"], -1.0, 0.0)

    pflag = feat["pulse_flag"].to_numpy(dtype=float)
    pflag_h = window_last(pflag, horizon)
    occ["pflag_at_h"] = pflag > 0.5
    occ["pquiet_at_h"] = pflag < 0.5
    bits["pflag_at_h"] = np.isfinite(pflag_h) & (pflag_h > 0.5)
    bits["pquiet_at_h"] = np.isfinite(pflag_h) & (pflag_h < 0.5)
    sides["pflag_at_h"] = np.where(bits["pflag_at_h"], 1.0, 0.0)
    sides["pquiet_at_h"] = np.where(bits["pquiet_at_h"], -1.0, 0.0)
    occ["pflag_any"] = pflag > 0.5
    occ["pquiet_all"] = pflag < 0.5
    bits["pflag_any"] = any_in_next(pflag > 0.5, horizon)
    bits["pquiet_all"] = (~bits["pflag_any"]) & (np.arange(n) + horizon < n)
    sides["pflag_any"] = np.where(bits["pflag_any"], 1.0, 0.0)
    sides["pquiet_all"] = np.where(bits["pquiet_all"], -1.0, 0.0)

    e12 = ema(close, 12)
    with np.errstate(divide="ignore", invalid="ignore"):
        e12_dist = (close - e12) / np.where(np.abs(close) > 1e-12, close, np.nan)
    e12_h = window_last(e12_dist, horizon)
    occ["ema12_above_at_h"] = e12_dist > 0.0
    occ["ema12_below_at_h"] = e12_dist < 0.0
    bits["ema12_above_at_h"] = np.isfinite(e12_h) & (e12_h > 0.0)
    bits["ema12_below_at_h"] = np.isfinite(e12_h) & (e12_h < 0.0)
    sides["ema12_above_at_h"] = np.where(bits["ema12_above_at_h"], 1.0, 0.0)
    sides["ema12_below_at_h"] = np.where(bits["ema12_below_at_h"], -1.0, 0.0)
    occ["ema12_cross_up"] = cross_up(e12_dist, 0.0)
    occ["ema12_cross_down"] = cross_down(e12_dist, 0.0)
    bits["ema12_cross_up"] = any_in_next(occ["ema12_cross_up"], horizon)
    bits["ema12_cross_down"] = any_in_next(occ["ema12_cross_down"], horizon)
    sides["ema12_cross_up"] = np.where(bits["ema12_cross_up"], 1.0, 0.0)
    sides["ema12_cross_down"] = np.where(bits["ema12_cross_down"], -1.0, 0.0)

    open_ = df["open"].to_numpy(dtype=float) if "open" in df.columns else close
    body = close - open_
    body_h = window_last(body, horizon)
    occ["body_up_at_h"] = body > 0.0
    occ["body_dn_at_h"] = body < 0.0
    bits["body_up_at_h"] = np.isfinite(body_h) & (body_h > 0.0)
    bits["body_dn_at_h"] = np.isfinite(body_h) & (body_h < 0.0)
    sides["body_up_at_h"] = np.where(bits["body_up_at_h"], 1.0, 0.0)
    sides["body_dn_at_h"] = np.where(bits["body_dn_at_h"], -1.0, 0.0)
    occ["body_cross_up_0"] = cross_up(body, 0.0)
    occ["body_cross_down_0"] = cross_down(body, 0.0)
    bits["body_cross_up_0"] = any_in_next(occ["body_cross_up_0"], horizon)
    bits["body_cross_down_0"] = any_in_next(occ["body_cross_down_0"], horizon)
    sides["body_cross_up_0"] = np.where(bits["body_cross_up_0"], 1.0, 0.0)
    sides["body_cross_down_0"] = np.where(bits["body_cross_down_0"], -1.0, 0.0)

    s20 = sma(close, 20)
    with np.errstate(divide="ignore", invalid="ignore"):
        s20_dist = (close - s20) / np.where(np.abs(close) > 1e-12, close, np.nan)
    s20_h = window_last(s20_dist, horizon)
    occ["sma20_above_at_h"] = s20_dist > 0.0
    occ["sma20_below_at_h"] = s20_dist < 0.0
    bits["sma20_above_at_h"] = np.isfinite(s20_h) & (s20_h > 0.0)
    bits["sma20_below_at_h"] = np.isfinite(s20_h) & (s20_h < 0.0)
    sides["sma20_above_at_h"] = np.where(bits["sma20_above_at_h"], 1.0, 0.0)
    sides["sma20_below_at_h"] = np.where(bits["sma20_below_at_h"], -1.0, 0.0)
    occ["sma20_cross_up"] = cross_up(s20_dist, 0.0)
    occ["sma20_cross_down"] = cross_down(s20_dist, 0.0)
    bits["sma20_cross_up"] = any_in_next(occ["sma20_cross_up"], horizon)
    bits["sma20_cross_down"] = any_in_next(occ["sma20_cross_down"], horizon)
    sides["sma20_cross_up"] = np.where(bits["sma20_cross_up"], 1.0, 0.0)
    sides["sma20_cross_down"] = np.where(bits["sma20_cross_down"], -1.0, 0.0)

    e26 = ema(close, 26)
    with np.errstate(divide="ignore", invalid="ignore"):
        e26_dist = (close - e26) / np.where(np.abs(close) > 1e-12, close, np.nan)
    e26_h = window_last(e26_dist, horizon)
    occ["ema26_above_at_h"] = e26_dist > 0.0
    occ["ema26_below_at_h"] = e26_dist < 0.0
    bits["ema26_above_at_h"] = np.isfinite(e26_h) & (e26_h > 0.0)
    bits["ema26_below_at_h"] = np.isfinite(e26_h) & (e26_h < 0.0)
    sides["ema26_above_at_h"] = np.where(bits["ema26_above_at_h"], 1.0, 0.0)
    sides["ema26_below_at_h"] = np.where(bits["ema26_below_at_h"], -1.0, 0.0)
    occ["ema26_cross_up"] = cross_up(e26_dist, 0.0)
    occ["ema26_cross_down"] = cross_down(e26_dist, 0.0)
    bits["ema26_cross_up"] = any_in_next(occ["ema26_cross_up"], horizon)
    bits["ema26_cross_down"] = any_in_next(occ["ema26_cross_down"], horizon)
    sides["ema26_cross_up"] = np.where(bits["ema26_cross_up"], 1.0, 0.0)
    sides["ema26_cross_down"] = np.where(bits["ema26_cross_down"], -1.0, 0.0)

    engulf_up = np.zeros(n, dtype=bool)
    engulf_dn = np.zeros(n, dtype=bool)
    if n > 1:
        cur_up = close > open_
        cur_dn = close < open_
        prev_up = np.zeros(n, dtype=bool)
        prev_dn = np.zeros(n, dtype=bool)
        prev_up[1:] = close[:-1] > open_[:-1]
        prev_dn[1:] = close[:-1] < open_[:-1]
        engulf_up[1:] = (
            cur_up[1:]
            & prev_dn[1:]
            & (close[1:] > open_[:-1])
            & (open_[1:] < close[:-1])
        )
        engulf_dn[1:] = (
            cur_dn[1:]
            & prev_up[1:]
            & (close[1:] < open_[:-1])
            & (open_[1:] > close[:-1])
        )
    occ["engulf_up_at_h"] = engulf_up
    occ["engulf_dn_at_h"] = engulf_dn
    bits["engulf_up_at_h"] = window_last(engulf_up.astype(float), horizon) > 0.5
    bits["engulf_dn_at_h"] = window_last(engulf_dn.astype(float), horizon) > 0.5
    sides["engulf_up_at_h"] = np.where(bits["engulf_up_at_h"], 1.0, 0.0)
    sides["engulf_dn_at_h"] = np.where(bits["engulf_dn_at_h"], -1.0, 0.0)
    occ["engulf_up_any"] = engulf_up
    occ["engulf_dn_any"] = engulf_dn
    bits["engulf_up_any"] = any_in_next(engulf_up, horizon)
    bits["engulf_dn_any"] = any_in_next(engulf_dn, horizon)
    sides["engulf_up_any"] = np.where(bits["engulf_up_any"], 1.0, 0.0)
    sides["engulf_dn_any"] = np.where(bits["engulf_dn_any"], -1.0, 0.0)

    with np.errstate(divide="ignore", invalid="ignore"):
        clpos = (close - low) / np.where(np.abs(high - low) > 1e-12, high - low, np.nan)
    clpos_h = window_last(clpos, horizon)
    occ["clpos_high_at_h"] = clpos > 0.8
    occ["clpos_low_at_h"] = clpos < 0.2
    bits["clpos_high_at_h"] = np.isfinite(clpos_h) & (clpos_h > 0.8)
    bits["clpos_low_at_h"] = np.isfinite(clpos_h) & (clpos_h < 0.2)
    sides["clpos_high_at_h"] = np.where(bits["clpos_high_at_h"], 1.0, 0.0)
    sides["clpos_low_at_h"] = np.where(bits["clpos_low_at_h"], -1.0, 0.0)
    occ["clpos_cross_up_08"] = cross_up(clpos, 0.8)
    occ["clpos_cross_down_02"] = cross_down(clpos, 0.2)
    bits["clpos_cross_up_08"] = any_in_next(occ["clpos_cross_up_08"], horizon)
    bits["clpos_cross_down_02"] = any_in_next(occ["clpos_cross_down_02"], horizon)
    sides["clpos_cross_up_08"] = np.where(bits["clpos_cross_up_08"], 1.0, 0.0)
    sides["clpos_cross_down_02"] = np.where(bits["clpos_cross_down_02"], -1.0, 0.0)

    up3 = np.zeros(n, dtype=bool)
    dn3 = np.zeros(n, dtype=bool)
    if n > 2:
        up3[2:] = (close[2:] > close[1:-1]) & (close[1:-1] > close[:-2])
        dn3[2:] = (close[2:] < close[1:-1]) & (close[1:-1] < close[:-2])
    occ["up3_at_h"] = up3
    occ["dn3_at_h"] = dn3
    bits["up3_at_h"] = window_last(up3.astype(float), horizon) > 0.5
    bits["dn3_at_h"] = window_last(dn3.astype(float), horizon) > 0.5
    sides["up3_at_h"] = np.where(bits["up3_at_h"], 1.0, 0.0)
    sides["dn3_at_h"] = np.where(bits["dn3_at_h"], -1.0, 0.0)
    occ["up3_any"] = up3
    occ["dn3_any"] = dn3
    bits["up3_any"] = any_in_next(up3, horizon)
    bits["dn3_any"] = any_in_next(dn3, horizon)
    sides["up3_any"] = np.where(bits["up3_any"], 1.0, 0.0)
    sides["dn3_any"] = np.where(bits["dn3_any"], -1.0, 0.0)

    vol = (
        df["volume"].to_numpy(dtype=float)
        if "volume" in df.columns
        else np.ones(n, dtype=float)
    )
    with np.errstate(divide="ignore", invalid="ignore"):
        vr = vol / sma(vol, 20)
    vr_h = window_last(vr, horizon)
    occ["vr_high_at_h"] = vr > 1.5
    occ["vr_low_at_h"] = vr < 0.7
    bits["vr_high_at_h"] = np.isfinite(vr_h) & (vr_h > 1.5)
    bits["vr_low_at_h"] = np.isfinite(vr_h) & (vr_h < 0.7)
    sides["vr_high_at_h"] = np.where(bits["vr_high_at_h"], -1.0, 0.0)
    sides["vr_low_at_h"] = np.where(bits["vr_low_at_h"], 1.0, 0.0)
    occ["vr_cross_up_15"] = cross_up(vr, 1.5)
    occ["vr_cross_down_07"] = cross_down(vr, 0.7)
    bits["vr_cross_up_15"] = any_in_next(occ["vr_cross_up_15"], horizon)
    bits["vr_cross_down_07"] = any_in_next(occ["vr_cross_down_07"], horizon)
    sides["vr_cross_up_15"] = np.where(bits["vr_cross_up_15"], -1.0, 0.0)
    sides["vr_cross_down_07"] = np.where(bits["vr_cross_down_07"], 1.0, 0.0)

    bbw = feat["bb_width"].to_numpy(dtype=float)
    bbw_h = window_last(bbw, horizon)
    occ["bbw_high_at_h"] = bbw > 0.02
    occ["bbw_low_at_h"] = bbw < 0.008
    bits["bbw_high_at_h"] = np.isfinite(bbw_h) & (bbw_h > 0.02)
    bits["bbw_low_at_h"] = np.isfinite(bbw_h) & (bbw_h < 0.008)
    sides["bbw_high_at_h"] = np.where(bits["bbw_high_at_h"], -1.0, 0.0)
    sides["bbw_low_at_h"] = np.where(bits["bbw_low_at_h"], 1.0, 0.0)
    occ["bbw_cross_up_p02"] = cross_up(bbw, 0.02)
    occ["bbw_cross_down_p008"] = cross_down(bbw, 0.008)
    bits["bbw_cross_up_p02"] = any_in_next(occ["bbw_cross_up_p02"], horizon)
    bits["bbw_cross_down_p008"] = any_in_next(occ["bbw_cross_down_p008"], horizon)
    sides["bbw_cross_up_p02"] = np.where(bits["bbw_cross_up_p02"], -1.0, 0.0)
    sides["bbw_cross_down_p008"] = np.where(bits["bbw_cross_down_p008"], 1.0, 0.0)

    kcw = feat["kc_width"].to_numpy(dtype=float)
    kcw_h = window_last(kcw, horizon)
    occ["kcw_wide_at_h"] = kcw > 0.03
    occ["kcw_tight_at_h"] = kcw < 0.01
    bits["kcw_wide_at_h"] = np.isfinite(kcw_h) & (kcw_h > 0.03)
    bits["kcw_tight_at_h"] = np.isfinite(kcw_h) & (kcw_h < 0.01)
    sides["kcw_wide_at_h"] = np.where(bits["kcw_wide_at_h"], -1.0, 0.0)
    sides["kcw_tight_at_h"] = np.where(bits["kcw_tight_at_h"], 1.0, 0.0)
    occ["kcw_cross_up_03"] = cross_up(kcw, 0.03)
    occ["kcw_cross_down_01"] = cross_down(kcw, 0.01)
    bits["kcw_cross_up_03"] = any_in_next(occ["kcw_cross_up_03"], horizon)
    bits["kcw_cross_down_01"] = any_in_next(occ["kcw_cross_down_01"], horizon)
    sides["kcw_cross_up_03"] = np.where(bits["kcw_cross_up_03"], -1.0, 0.0)
    sides["kcw_cross_down_01"] = np.where(bits["kcw_cross_down_01"], 1.0, 0.0)

    up5 = np.zeros(n, dtype=bool)
    dn5 = np.zeros(n, dtype=bool)
    if n > 4:
        up5[4:] = (
            (close[4:] > close[3:-1])
            & (close[3:-1] > close[2:-2])
            & (close[2:-2] > close[1:-3])
            & (close[1:-3] > close[:-4])
        )
        dn5[4:] = (
            (close[4:] < close[3:-1])
            & (close[3:-1] < close[2:-2])
            & (close[2:-2] < close[1:-3])
            & (close[1:-3] < close[:-4])
        )
    up5_start = np.zeros(n, dtype=bool)
    dn5_start = np.zeros(n, dtype=bool)
    if n > 1:
        up5_start[1:] = up5[1:] & ~up5[:-1]
        dn5_start[1:] = dn5[1:] & ~dn5[:-1]
    occ["up5_at_h"] = up5
    occ["dn5_at_h"] = dn5
    bits["up5_at_h"] = window_last(up5.astype(float), horizon) > 0.5
    bits["dn5_at_h"] = window_last(dn5.astype(float), horizon) > 0.5
    sides["up5_at_h"] = np.where(bits["up5_at_h"], 1.0, 0.0)
    sides["dn5_at_h"] = np.where(bits["dn5_at_h"], -1.0, 0.0)
    occ["up5_start"] = up5_start
    occ["dn5_start"] = dn5_start
    bits["up5_start"] = any_in_next(up5_start, horizon)
    bits["dn5_start"] = any_in_next(dn5_start, horizon)
    sides["up5_start"] = np.where(bits["up5_start"], 1.0, 0.0)
    sides["dn5_start"] = np.where(bits["dn5_start"], -1.0, 0.0)

    with np.errstate(divide="ignore", invalid="ignore"):
        body_rng = np.abs(close - open_) / np.where(np.abs(high - low) > 1e-12, high - low, np.nan)
    doji = np.isfinite(body_rng) & (body_rng < 0.1)
    widebody = np.isfinite(body_rng) & (body_rng > 0.7)
    occ["doji_at_h"] = doji
    occ["widebody_at_h"] = widebody
    bits["doji_at_h"] = window_last(doji.astype(float), horizon) > 0.5
    bits["widebody_at_h"] = window_last(widebody.astype(float), horizon) > 0.5
    sides["doji_at_h"] = np.where(bits["doji_at_h"], 1.0, 0.0)
    sides["widebody_at_h"] = np.where(bits["widebody_at_h"], -1.0, 0.0)
    occ["doji_enter"] = cross_down(body_rng, 0.1)
    occ["widebody_enter"] = cross_up(body_rng, 0.7)
    bits["doji_enter"] = any_in_next(occ["doji_enter"], horizon)
    bits["widebody_enter"] = any_in_next(occ["widebody_enter"], horizon)
    sides["doji_enter"] = np.where(bits["doji_enter"], 1.0, 0.0)
    sides["widebody_enter"] = np.where(bits["widebody_enter"], -1.0, 0.0)

    with np.errstate(divide="ignore", invalid="ignore"):
        rng = np.where(np.abs(high - low) > 1e-12, high - low, np.nan)
        lpin = (np.minimum(open_, close) - low) / rng > 0.6
        upin = (high - np.maximum(open_, close)) / rng > 0.6
    lpin = np.isfinite(lpin) & lpin
    upin = np.isfinite(upin) & upin
    lpin_start = np.zeros(n, dtype=bool)
    upin_start = np.zeros(n, dtype=bool)
    if n > 1:
        lpin_start[1:] = lpin[1:] & ~lpin[:-1]
        upin_start[1:] = upin[1:] & ~upin[:-1]
    occ["lpin_at_h"] = lpin
    occ["upin_at_h"] = upin
    bits["lpin_at_h"] = window_last(lpin.astype(float), horizon) > 0.5
    bits["upin_at_h"] = window_last(upin.astype(float), horizon) > 0.5
    sides["lpin_at_h"] = np.where(bits["lpin_at_h"], 1.0, 0.0)
    sides["upin_at_h"] = np.where(bits["upin_at_h"], -1.0, 0.0)
    occ["lpin_start"] = lpin_start
    occ["upin_start"] = upin_start
    bits["lpin_start"] = any_in_next(lpin_start, horizon)
    bits["upin_start"] = any_in_next(upin_start, horizon)
    sides["lpin_start"] = np.where(bits["lpin_start"], 1.0, 0.0)
    sides["upin_start"] = np.where(bits["upin_start"], -1.0, 0.0)

    std20 = pd.Series(close).rolling(20, min_periods=10).std(ddof=0).to_numpy()
    with np.errstate(divide="ignore", invalid="ignore"):
        cz = (close - s20) / np.where(np.abs(std20) > 1e-12, std20, np.nan)
    cz_h = window_last(cz, horizon)
    occ["cz_high_at_h"] = cz > 1.0
    occ["cz_low_at_h"] = cz < -1.0
    bits["cz_high_at_h"] = np.isfinite(cz_h) & (cz_h > 1.0)
    bits["cz_low_at_h"] = np.isfinite(cz_h) & (cz_h < -1.0)
    sides["cz_high_at_h"] = np.where(bits["cz_high_at_h"], -1.0, 0.0)
    sides["cz_low_at_h"] = np.where(bits["cz_low_at_h"], 1.0, 0.0)
    occ["cz_cross_up_1"] = cross_up(cz, 1.0)
    occ["cz_cross_down_neg1"] = cross_down(cz, -1.0)
    bits["cz_cross_up_1"] = any_in_next(occ["cz_cross_up_1"], horizon)
    bits["cz_cross_down_neg1"] = any_in_next(occ["cz_cross_down_neg1"], horizon)
    sides["cz_cross_up_1"] = np.where(bits["cz_cross_up_1"], -1.0, 0.0)
    sides["cz_cross_down_neg1"] = np.where(bits["cz_cross_down_neg1"], 1.0, 0.0)

    bar_rng = high - low
    with np.errstate(divide="ignore", invalid="ignore"):
        rr = bar_rng / sma(bar_rng, 20)
    rr_h = window_last(rr, horizon)
    occ["rr_wide_at_h"] = rr > 1.5
    occ["rr_tight_at_h"] = rr < 0.6
    bits["rr_wide_at_h"] = np.isfinite(rr_h) & (rr_h > 1.5)
    bits["rr_tight_at_h"] = np.isfinite(rr_h) & (rr_h < 0.6)
    sides["rr_wide_at_h"] = np.where(bits["rr_wide_at_h"], -1.0, 0.0)
    sides["rr_tight_at_h"] = np.where(bits["rr_tight_at_h"], 1.0, 0.0)
    occ["rr_cross_up_15"] = cross_up(rr, 1.5)
    occ["rr_cross_down_06"] = cross_down(rr, 0.6)
    bits["rr_cross_up_15"] = any_in_next(occ["rr_cross_up_15"], horizon)
    bits["rr_cross_down_06"] = any_in_next(occ["rr_cross_down_06"], horizon)
    sides["rr_cross_up_15"] = np.where(bits["rr_cross_up_15"], -1.0, 0.0)
    sides["rr_cross_down_06"] = np.where(bits["rr_cross_down_06"], 1.0, 0.0)

    s10 = sma(close, 10)
    with np.errstate(divide="ignore", invalid="ignore"):
        s10_dist = (close - s10) / np.where(np.abs(close) > 1e-12, close, np.nan)
    s10_h = window_last(s10_dist, horizon)
    occ["sma10_above_at_h"] = s10_dist > 0.0
    occ["sma10_below_at_h"] = s10_dist < 0.0
    bits["sma10_above_at_h"] = np.isfinite(s10_h) & (s10_h > 0.0)
    bits["sma10_below_at_h"] = np.isfinite(s10_h) & (s10_h < 0.0)
    sides["sma10_above_at_h"] = np.where(bits["sma10_above_at_h"], 1.0, 0.0)
    sides["sma10_below_at_h"] = np.where(bits["sma10_below_at_h"], -1.0, 0.0)
    occ["sma10_cross_up"] = cross_up(s10_dist, 0.0)
    occ["sma10_cross_down"] = cross_down(s10_dist, 0.0)
    bits["sma10_cross_up"] = any_in_next(occ["sma10_cross_up"], horizon)
    bits["sma10_cross_down"] = any_in_next(occ["sma10_cross_down"], horizon)
