    sides["sma2100_below_at_h"] = np.where(bits["sma2100_below_at_h"], -1.0, 0.0)
    occ["sma2100_cross_up"] = cross_up(s2100_dist, 0.0)
    occ["sma2100_cross_down"] = cross_down(s2100_dist, 0.0)
    bits["sma2100_cross_up"] = any_in_next(occ["sma2100_cross_up"], horizon)
    bits["sma2100_cross_down"] = any_in_next(occ["sma2100_cross_down"], horizon)
    sides["sma2100_cross_up"] = np.where(bits["sma2100_cross_up"], 1.0, 0.0)
    sides["sma2100_cross_down"] = np.where(bits["sma2100_cross_down"], -1.0, 0.0)

    e2060 = ema(close, 2060)
    with np.errstate(divide="ignore", invalid="ignore"):
        e2060_dist = (close - e2060) / np.where(np.abs(close) > 1e-12, close, np.nan)
    e2060_h = window_last(e2060_dist, horizon)
    occ["ema2060_above_at_h"] = e2060_dist > 0.0
    occ["ema2060_below_at_h"] = e2060_dist < 0.0
    bits["ema2060_above_at_h"] = np.isfinite(e2060_h) & (e2060_h > 0.0)
    bits["ema2060_below_at_h"] = np.isfinite(e2060_h) & (e2060_h < 0.0)
    sides["ema2060_above_at_h"] = np.where(bits["ema2060_above_at_h"], 1.0, 0.0)
    sides["ema2060_below_at_h"] = np.where(bits["ema2060_below_at_h"], -1.0, 0.0)
    occ["ema2060_cross_up"] = cross_up(e2060_dist, 0.0)
    occ["ema2060_cross_down"] = cross_down(e2060_dist, 0.0)
    bits["ema2060_cross_up"] = any_in_next(occ["ema2060_cross_up"], horizon)
    bits["ema2060_cross_down"] = any_in_next(occ["ema2060_cross_down"], horizon)
    sides["ema2060_cross_up"] = np.where(bits["ema2060_cross_up"], 1.0, 0.0)
    sides["ema2060_cross_down"] = np.where(bits["ema2060_cross_down"], -1.0, 0.0)

    ret856 = np.full(n, np.nan)
    if n > 856:
        ret856[856:] = close[856:] / np.where(close[:-856] > 0, close[:-856], np.nan) - 1.0
    ret856_h = window_last(ret856, horizon)
    occ["ret856_pos_at_h"] = ret856 > 0.0
    occ["ret856_neg_at_h"] = ret856 < 0.0
    bits["ret856_pos_at_h"] = np.isfinite(ret856_h) & (ret856_h > 0.0)
    bits["ret856_neg_at_h"] = np.isfinite(ret856_h) & (ret856_h < 0.0)
    sides["ret856_pos_at_h"] = np.where(bits["ret856_pos_at_h"], 1.0, 0.0)
    sides["ret856_neg_at_h"] = np.where(bits["ret856_neg_at_h"], -1.0, 0.0)
    occ["ret856_cross_up_0"] = cross_up(ret856, 0.0)
    occ["ret856_cross_down_0"] = cross_down(ret856, 0.0)
    bits["ret856_cross_up_0"] = any_in_next(occ["ret856_cross_up_0"], horizon)
    bits["ret856_cross_down_0"] = any_in_next(occ["ret856_cross_down_0"], horizon)
    sides["ret856_cross_up_0"] = np.where(bits["ret856_cross_up_0"], 1.0, 0.0)
    sides["ret856_cross_down_0"] = np.where(bits["ret856_cross_down_0"], -1.0, 0.0)

    emit_auto_windows_for_ids(
        close=close,
        high=high,
        low=low,
        n=n,
        horizon=horizon,
        occ=occ,
        bits=bits,
        sides=sides,
        ids=ids,
    )

    valid = np.arange(n) + horizon < n
    labels = pd.DataFrame(index=df.index)
    side_df = pd.DataFrame(index=df.index)
    occ_df = pd.DataFrame(index=df.index)
    for eid in ids:
        lab = bits[eid].astype(float)
        lab[~valid] = np.nan
        labels[eid] = lab
        sd = sides[eid].astype(float)
        sd[~valid] = np.nan
        sd[lab != 1.0] = 0.0
        side_df[eid] = sd
        occ_df[eid] = occ[eid].astype(float)
    return AutonomyPack(
        horizon=int(horizon),
        features=feat,
        labels=labels,
        side=side_df,
        occurrence=occ_df,
        event_ids=ids,
    )
